package glitch

import data.glitch_lib

credential_keywords := {
    "password", "secret", "key", "token", "credential",
    "api_key", "secret_key", "access_key", "connection_string", "dsn",
    "admin_password", "root_password", "encryption_key", "jwt_secret"
}

contains_keyword(name) {
    keyword := credential_keywords[_]
    regex.match(sprintf("(?i).*%s.*", [keyword]), name)
}

check_hardcoded_credential(value) {
    value.ir_type == "String"
    # Check if the string value looks like a hard-coded credential
    # (not empty, not a variable reference, and not obviously a placeholder)
    value.value != ""
    not regex.match("(?i)^(var\\.|\\$|\\{.*\\}|<.*>)$", value.value)
} else {
    # Also flag if it's a function call that might read from a file (e.g., file("path"))
    value.ir_type == "FunctionCall"
    contains(value.name, "file")
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check if the attribute name contains any credential keyword
    contains_keyword(attr.name)

    # Check if the value is a hard-coded credential
    check_hardcoded_credential(attr.value)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Avoid storing credentials in plain text. (CWE-798)"
    }
}

